test_lines = test_input_text.strip().split('\n')[1:]
test_grid = [[int(x) for x in line.split()] for line in test_lines]

demo_input_start = content.find("Demo pair 1 input (30x30)")
demo_input_end = content.find("Demo pair 1 output", demo_input_start)
demo_input_text = content[demo_input_start:demo_input_end].replace('\\n', '\n')
demo_lines = demo_input_text.strip().split('\n')[1:]
demo_grid = [[int(x) for x in line.split()] for line in demo_lines]

demo_output_start = content.find("Demo pair 1 output (30x30)")
demo_output_end = content.find("Same instance", demo_output_start)
demo_output_text = content[demo_output_start:demo_output_end].replace('\\n', '\n')
demo_output_lines = demo_output_text.strip().split('\n')[1:]
demo_output_grid = [[int(x) for x in line.split()] for line in demo_output_lines]

# My hypothesis:
# 1. Find all cells with count=1 (rare colors)
# 2. For each such cell at (r, c) with color v: add v to set(row_colors[r] and col_colors[c])
# 3. Output: if cell is at intersection of multiple colors, become background (most common non-zero in input)
#           if cell has exactly one color, become that color
#           else remain background

def transform1(input_grid):
    """Attempt 1: Row/column line fill from rare colors"""
    rows, cols = len(input_grid), len(input_grid[0])
    counts = Counter([v for row in input_grid for v in row])
    rare = {c for c, cnt in counts.items() if cnt == 1}

    row_colors = set()
    col_colors = set()
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] in rare:
                row_colors.add(r)
                col_colors.add(c)

    # Build what colors should fill each row/col (collectively across all rare positions)
    row_fill = {r: [] for r in range(rows)}
    col_fill = {c: [] for c in range(cols)}

    for r in row_colors:
        for c in range(cols):
            for rc in row_colors:
                if input_grid[rc][c] in rare:
                    row_fill[r].append(input_grid[rc][c])

    for c in col_colors:
        for r in range(rows):
            for cc in col_colors:
                if input_grid[r][cc] in rare:
                    col_fill[c].append(input_grid[r][cc])

    # Determine background color (most common non-zero)
    nonzero = [v for r in input_grid[0] for v in r if v != 0]
    nonzero_counts = Counter(nonzero)
    bg_color = max(nonzero_counts, key=nonzero_counts.get)

    output_grid = [[bg_color for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] in rare:
                output_grid[r][c] = input_grid[r][c]
            else:
                r_colors = set()
                c_colors = set()
                for other_r in range(rows):
                    if input_grid[other_r][c] in rare:
                        r_colors.add(input_grid[other_r][c])
                for other_c in range(cols):
                    if input_grid[r][other_c] in rare:
                        c_colors.add(input_grid[r][other_c])

                if len(r_colors) == 1 and len(c_colors) == 0:
                    output_grid[r][c] = list(r_colors)[0]
                elif len(c_colors) == 1 and len(r_colors) == 0:
                    output_grid[r][c] = list(c_colors)[0]
                elif len(r_colors) > 1 or len(c_colors) > 1:
                    output_grid[r][c] = bg_color
                else:
                    # Check if this cell is at intersection of the same color
                    for rr in row_colors:
                        for cc in col_colors:
                            if input_grid[rr][cc] in rare:
                                pass
                else:
                    output_grid[r][c] = bg_color

    return output_grid

# Compare with actual demo output
print("Comparing output at key positions...")
for r in [0, 1, 2, 3, 4, 21]:
    for c in [5, 6, 20, 22]:
        o1 = transform1(demo_grid)[r][c]
        o2 = demo_output_grid[r][c]
        match = "✓" if o1 == o2 else f"✗"
        print(f"  [{r},{c}]: predicted={o1}, actual={o2} {match}")

